{"query":"WITH universe AS (
 SELECT Gene, Ensembl FROM proteinatlas WHERE Ensembl IS NOT NULL AND "Protein class" ILIKE '%Predicted membrane proteins%'
), normal_rows AS (
 SELECT u.Ensembl,u.Gene,n.Tissue,n.Level,n.Reliability,CASE n.Level WHEN 'High' THEN 3 WHEN 'Medium' THEN 2 WHEN 'Low' THEN 1 WHEN 'Not detected' THEN 0 END score
 FROM universe u JOIN normal_ihc_data n ON n.Gene=u.Ensembl
 WHERE n.Reliability IN ('Enhanced','Supported') AND ((n.Tissue='Colon' AND n."Cell type"='glandular cells') OR (n.Tissue='Breast' AND n."Cell type"='glandular cells') OR (n.Tissue='Lung' AND n."Cell type"='alveolar cells'))
), normal AS (SELECT Ensembl,Gene,Tissue,max(score) normal_score FROM normal_rows GROUP BY 1,2,3),
cancer AS (
 SELECT u.Ensembl,u.Gene,c.Cancer, SUM(3*TRY_CAST(c.High AS DOUBLE)+2*TRY_CAST(c.Medium AS DOUBLE)+TRY_CAST(c.Low AS DOUBLE))/NULLIF(SUM(TRY_CAST(c.High AS DOUBLE)+TRY_CAST(c.Medium AS DOUBLE)+TRY_CAST(c.Low AS DOUBLE)+TRY_CAST(c."Not detected" AS DOUBLE)),0) cancer_score, SUM(TRY_CAST(c.High AS BIGINT)+TRY_CAST(c.Medium AS BIGINT)+TRY_CAST(c.Low AS BIGINT)+TRY_CAST(c."Not detected" AS BIGINT)) n
 FROM universe u JOIN cancer_data c ON c.Gene=u.Ensembl WHERE c.Cancer IN ('colorectal cancer','breast cancer','lung cancer') GROUP BY 1,2,3 HAVING SUM(TRY_CAST(c.High AS BIGINT)+TRY_CAST(c.Medium AS BIGINT)+TRY_CAST(c.Low AS BIGINT)+TRY_CAST(c."Not detected" AS BIGINT)) >= 5
),pairs AS (SELECT n.Ensembl,n.Gene,n.Tissue,n.normal_score,c.Cancer,c.cancer_score,c.cancer_score-n.normal_score change FROM normal n JOIN cancer c ON c.Ensembl=n.Ensembl AND ((n.Tissue='Colon' AND c.Cancer='colorectal cancer') OR (n.Tissue='Breast' AND c.Cancer='breast cancer') OR (n.Tissue='Lung' AND c.Cancer='lung cancer')))
SELECT Tissue,Cancer,count(*) genes_both,median(change) median_change,sum(change>=1) increased_n,sum(change>=1)*1.0/count(*) fraction_increased FROM pairs GROUP BY 1,2 ORDER BY CASE Tissue WHEN 'Colon' THEN 1 WHEN 'Breast' THEN 2 WHEN 'Lung' THEN 3 END"}
